import { buildGraphSpatialIndex } from "../../lib/geospatial/decisionEngine.js";

export const AUCKLAND_BASELINE_METADATA = Object.freeze({"name":"Compact Auckland baseline arterial road graph","source":"OpenStreetMap via Overpass","sourceEndpoint":"https://overpass-api.de/api/interpreter","snapshotDate":"2026-08-29","version":"auckland-arterial-2026-08-30-v1","bbox":[-36.935,174.72,-36.84,174.825],"sourceNodeCount":21181,"sourceEdgeCount":34180,"nodeCount":1658,"edgeCount":3376,"speedAssumptions":"OSM maxspeed when present; otherwise highway-class defaults in decisionEngine.parseOverpassGraph","includedHighways":"motorway, trunk, primary, secondary, tertiary and their link classes"});

const COMPRESSED_SNAPSHOT = "";

function decodeBase64(value) {
  const binary = globalThis.atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export function graphFromCompactSnapshot(snapshot) {
  if (
    !snapshot?.metadata?.version ||
    !Array.isArray(snapshot.nodes) ||
    !snapshot.nodes.length ||
    !Array.isArray(snapshot.edges) ||
    !snapshot.edges.length
  ) {
    throw new RangeError("Malformed Auckland baseline graph snapshot");
  }
  const nodes = new Map(snapshot.nodes.map((node) => [String(node.id), { ...node, id: String(node.id) }]));
  const edges = snapshot.edges.map((edge, id) => ({
    ...edge,
    id,
    from: String(edge.from),
    to: String(edge.to),
    segmentKey: edge.segmentKey || `${edge.from}:${edge.to}`,
  }));
  if (
    edges.some(
      (edge) =>
        !nodes.has(edge.from) ||
        !nodes.has(edge.to) ||
        !Number.isFinite(edge.lengthKm) ||
        edge.lengthKm < 0 ||
        !Number.isFinite(edge.timeMin) ||
        edge.timeMin <= 0,
    )
  ) {
    throw new RangeError("Auckland baseline graph contains invalid road edges");
  }
  const adjacency = new Map();
  for (const edge of edges) {
    if (!adjacency.has(edge.from)) adjacency.set(edge.from, []);
    adjacency.get(edge.from).push(edge.id);
  }
  const graph = {
    nodes,
    nodeList: [...nodes.values()],
    edges,
    adjacency,
    version: snapshot.metadata.version,
    metadata: Object.freeze(snapshot.metadata),
    maxSpeedKph: edges.reduce(
      (maximum, edge) => Math.max(maximum, (edge.lengthKm / edge.timeMin) * 60),
      5,
    ),
  };
  graph.spatialIndex = buildGraphSpatialIndex(graph);
  return graph;
}

let graphPromise;

export function loadAucklandBaselineGraph() {
  if (!graphPromise) {
    graphPromise = (async () => {
      const stream = new globalThis.Blob([decodeBase64(COMPRESSED_SNAPSHOT)])
        .stream()
        .pipeThrough(new globalThis.DecompressionStream("gzip"));
      const json = await new globalThis.Response(stream).text();
      return graphFromCompactSnapshot(JSON.parse(json));
    })();
  }
  return graphPromise;
}
